const ev = $('Evento do worker').first().json.body;
const j = ev.job;
const preview = $input.first().json.data ?? '';
const id = ev.job_id;
return [{ json: {
  reply_to: j.context?.discord?.message_id ?? null,
  channel_id: j.context?.discord?.channel_id ?? null,
  embed: {
    title: `📝 Corte #${id} — roteiro para aprovar`,
    description: '```\n' + preview.slice(0, 3900) + '\n```',
    color: 0xF1C40F,
    footer: `cortes #${id} · responda esta mensagem para pedir outro roteiro`
  },
  buttons: [
    { label: 'Aprovar', custom_id: `cortes:approve:${id}`, style: 'success' },
    { label: 'Refazer roteiro', custom_id: `cortes:replan:${id}`, style: 'primary' },
    { label: 'Cancelar', custom_id: `cortes:cancel:${id}`, style: 'danger' }
  ]
} }];

const ev = $input.first().json.body;
const j = ev.job;
const id = ev.job_id;
const tags = (j.hashtags || []).map(h => '#' + String(h).replace(/^#/, '')).join(' ');
const linhas = [
  `**${j.title ?? ''}** (${Math.round(j.output_duration_s ?? 0)}s, versão ${j.plan_version})`,
  j.changes ? `✏️ ${j.changes}` : null,
  '',
  `**Legenda do post:** ${j.caption ?? ''}`,
  tags,
  '',
  `Arquivo final (1080x1920): data/media/${j.output_path}`,
  '_Prévia comprimida abaixo. Para alterar: responda esta mensagem ou use o botão._'
].filter(x => x !== null);
return [{ json: {
  reply_to: j.context?.discord?.message_id ?? null,
  channel_id: j.context?.discord?.channel_id ?? null,
  embed: { title: `🎬 Corte #${id} pronto`, description: linhas.join('\n'), color: 0x2ECC71, footer: `cortes #${id}` },
  file_path: `cortes/${j.preview_path}`,
  file_name: `corte_${id}_v${j.plan_version}.mp4`,
  buttons: [ { label: 'Pedir alteração', custom_id: `cortes:revise:${id}`, style: 'primary' } ]
} }];

const ev = $input.first().json.body;
const j = ev.job;
const id = ev.job_id;
const falhou = ev.to === 'FAILED';
const buttons = falhou
  ? [ { label: 'Tentar de novo', custom_id: `cortes:retry:${id}`, style: 'primary' } ]
  : [ { label: 'Pedir alteração', custom_id: `cortes:revise:${id}`, style: 'primary' } ];
return [{ json: {
  reply_to: j.context?.discord?.message_id ?? null,
  channel_id: j.context?.discord?.channel_id ?? null,
  embed: {
    title: `❌ Corte #${id}: ${falhou ? 'falhou' : 'reprovado no controle de qualidade'}`,
    description: '```\n' + String(j.last_error ?? ev.note ?? '').slice(0, 1500) + '\n```',
    color: 0xE74C3C,
    footer: `cortes #${id}`
  },
  buttons
} }];
